pub fn TodoItem(props: { todo: Todo, onToggle: fn(id: i32) -> () }) -> Jsx { .. }

fn toggle(todos: Array<Todo>, id: i32) -> Array<Todo> {
  todos |> .map((t) => if t.id == id { #{ done: !t.done, ..t } } else { t })
}

pub fn stats(todos: Array<Todo>) -> { total: i32, done: i32 } {
  let total = todos.len();
  let done = todos.filter((t) => t.done).len();
  #{ total, done }
}

let #{ total, done } = stats(todos);   // 分割代入も同じ印で
